// Which Playwright specs a changed file can affect (used by affected.mjs). Two sources, both conservative:
//  - the import graph: a spec, and the helpers and sources a spec imports, directly or not (exact);
//  - the coverage map `apps/desktop/e2e/spec-map.json` (generated by `pnpm --filter @cadabracraft/desktop e2e:map`): for each
//    app source file, the specs whose run called a function in it.
// A file neither knows is `null`: the caller then runs every spec.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, posix } from "node:path";

export const SPEC_MAP_PATH = "apps/desktop/e2e/spec-map.json";
const specFile = /^apps\/desktop\/e2e\/.+\.spec\.ts$/;
const importRe = /(?:from|import)\s*\(?\s*["'](\.[^"']*)["']/g;
const EXTENSIONS = ["", ".ts", ".tsx", ".mjs", ".js", "/index.ts", "/index.tsx"];

/** `apps/desktop/e2e/a.spec.ts` as Playwright takes it (relative to apps/desktop). */
export const toSpecArg = (file) => file.replace(/^apps\/desktop\//, "");

/** The files `source` (at repo-relative `from`) imports by relative path, resolved with `exists`. Pure given `exists`. */
export function relativeImports(from, source, exists) {
  const found = [];
  for (const match of source.matchAll(importRe)) {
    const base = posix.normalize(posix.join(posix.dirname(from), match[1]));
    const hit = EXTENSIONS.map((ext) => base + ext).find((p) => exists(p));
    if (hit) found.push(hit);
  }
  return found;
}

/**
 * The forward import edges of every spec and of everything a spec reaches: `{ "apps/desktop/e2e/a.spec.ts": ["apps/desktop/e2e/support/x.ts"], ... }`.
 * Reads from `root` on disk.
 */
export function readImportGraph(root) {
  const exists = (p) => isFile(root, p) && !/\.(json|css)$/.test(p);
  const graph = {};
  const queue = listSpecs(root);
  while (queue.length > 0) {
    const file = queue.pop();
    if (graph[file]) continue;
    let source = "";
    try {
      source = readFileSync(join(root, file), "utf8");
    } catch {
      // A missing file has no edges.
    }
    graph[file] = relativeImports(file, source, exists);
    queue.push(...graph[file]);
  }
  return graph;
}

function isFile(root, p) {
  try {
    return statSync(join(root, p)).isFile();
  } catch {
    return false;
  }
}

function listSpecs(root, dir = "apps/desktop/e2e") {
  const out = [];
  for (const entry of readdirSync(join(root, dir), { withFileTypes: true })) {
    const path = `${dir}/${entry.name}`;
    if (entry.isDirectory()) out.push(...listSpecs(root, path));
    else if (specFile.test(path)) out.push(path);
  }
  return out;
}

/**
 * @param {Record<string, string[]>} graph forward import edges (see readImportGraph)
 * @param {{ specs: string[], files: Record<string, number[]> } | null} map the coverage map, or null when there is none
 * @returns {(file: string) => string[] | null} the specs (as Playwright takes them) a change to `file` can affect, or null for "unknown: run all"
 */
export function createSpecIndex(graph, map) {
  const importers = {};
  for (const [from, tos] of Object.entries(graph))
    for (const to of tos) (importers[to] ??= []).push(from);
  return (file) => {
    const specs = new Set();
    const seen = new Set([file]);
    for (const node of seen) {
      if (specFile.test(node)) specs.add(node);
      for (const parent of importers[node] ?? []) seen.add(parent);
    }
    const mapped = map?.files?.[file];
    if (mapped) for (const i of mapped) specs.add(`apps/desktop/${map.specs[i]}`);
    return specs.size > 0 ? [...specs].map(toSpecArg).sort() : null;
  };
}

/** The coverage map from `root`, or null when it is missing or unreadable. */
export function readSpecMap(root) {
  try {
    const map = JSON.parse(readFileSync(join(root, SPEC_MAP_PATH), "utf8"));
    return Array.isArray(map.specs) && map.files ? map : null;
  } catch {
    return null;
  }
}

/**
 * The specs for a set of changed files that can reach the app's pages: the union of `specsFor` over them, or `[]` (every
 * spec) as soon as one file is unknown.
 */
export function specsForAll(files, specsFor) {
  const all = new Set();
  for (const file of files) {
    const specs = specsFor(file);
    if (specs === null) return [];
    for (const s of specs) all.add(s);
  }
  return [...all].sort();
}

/** The Playwright shards for `count` named specs (one job up to 20 specs) or the whole suite (`count` 0). */
export function shardsFor(count) {
  const jobs = count === 0 ? 4 : Math.min(4, Math.ceil(count / 20));
  return Array.from({ length: jobs }, (_, i) => i + 1);
}
